// Glossaire de la formation : chaque terme a un id (utilisé par data-term="…"),
// une catégorie, son nom et une définition vulgarisée en français et en anglais.
// g(id, cat, [termFr, termEn], [defFr, defEn], [exempleFr, exampleEn]?)
const g = (id, cat, term, def, example) => ({
  id,
  cat,
  term: { fr: term[0], en: term[1] ?? term[0] },
  def: { fr: def[0], en: def[1] },
  ...(example ? { example: { fr: example[0], en: example[1] } } : {}),
});

